// ══════════════════════════════════════════════════════════════════════
// notifications.js — notification badge/panel and background fav polling
//
// Notifications are generated by `checkFavArtistEvents`, a background
// poll (every 30 min) that compares each followed artist's current
// Eventim concerts against the last-seen set and pushes a notification
// for every new productId. They live in `state.notifications`
// (persisted to localStorage under `kp-notifs`, capped at 50). The bell
// badge in the header reflects unread count; the dropdown panel lists
// notifications and opens an import modal on click.
//
// `startFavPolling` installs the interval; the module kicks both an
// initial check and the interval off 5s after import (module-level
// setTimeout), matching the original app.js behaviour, and refreshes
// the badge immediately on import.
// ══════════════════════════════════════════════════════════════════════

import { state } from './state.js';
import { esc, parseDate, fmtDateShort, venueMapHtml } from './utils.js';
import { openModal, closeModal } from './ui.js';
import { fetchAll } from './api.js';
import { icon } from './icons.js';

let _notifImportData = null;
let _lastEventimCheck = {};
let _pollInterval = null;

/** Cap `state.notifications` to the most recent 50 and persist to localStorage. */
export function saveNotifications() {
  state.notifications = state.notifications.slice(-50);
  localStorage.setItem('kp-notifs', JSON.stringify(state.notifications));
}

/** Update the `#notif-badge` unread count/visibility from `state.notifications`. */
export function updateNotifBadge() {
  const unread = state.notifications.filter(n=>!n.read).length;
  const badge = document.getElementById('notif-badge');
  badge.textContent = unread>9?'9+':String(unread);
  badge.classList.toggle('visible', unread>0);
}

/** Toggle the notification dropdown panel open/closed, rendering on open. */
export function toggleNotifPanel() {
  const p = document.getElementById('notif-panel');
  p.classList.toggle('open');
  if (p.classList.contains('open')) renderNotifPanel();
}

/** Render the notification list into `#notif-list` (most recent first). */
export function renderNotifPanel() {
  const el = document.getElementById('notif-list');
  if (!state.notifications.length) { el.innerHTML=`<div class="empty-state"><div class="icon">${icon('bell')}</div><h3>Keine Benachrichtigungen</h3><p>Neue Termine gefolgter Artists erscheinen hier.</p></div>`; return; }
  el.innerHTML = [...state.notifications].reverse().map(n=>`
    <div class="notif-item ${n.read?'':'unread'}" onclick="onNotifClick('${n.id}')">
      <div class="notif-artist">${icon('star-filled')} ${esc(n.artistName)}</div>
      <div class="notif-event">${icon('calendar')} ${n.date?fmtDateShort(n.date):'?'} · ${esc(n.venue||'')}${n.city?', '+esc(n.city):''}</div>
    </div>`).join('');
}

/**
 * Click handler for a notification row: mark it read, refresh badge/list,
 * open the event-import modal, then close the dropdown panel.
 * @param {string} notifId
 */
export function onNotifClick(notifId) {
  const notif = state.notifications.find(n=>n.id===notifId);
  if (!notif) return;
  notif.read=true; saveNotifications(); updateNotifBadge(); renderNotifPanel();
  openNotifEventModal(notif.concertData, notif.artistName);
  document.getElementById('notif-panel').classList.remove('open');
}

/** Mark every notification as read, persist and refresh badge + panel. */
export function markAllNotifRead() {
  state.notifications.forEach(n=>n.read=true);
  saveNotifications(); updateNotifBadge(); renderNotifPanel();
}

/**
 * Open the "Event speichern" modal for a discovered concert, stashing
 * the concert/artist pair in `_notifImportData` for `importNotifEvent`.
 * @param {any} concertData
 * @param {string} artistName
 */
export function openNotifEventModal(concertData, artistName) {
  _notifImportData = {concertData, artistName};
  const d = parseDate(concertData.date);
  document.getElementById('notif-event-title').textContent = `${esc(artistName)} – Event speichern`;
  document.getElementById('notif-event-body').innerHTML = `
    <div style="display:grid;grid-template-columns:72px 1fr;gap:14px;padding:4px 0 16px">
      <div class="date-block" style="padding-top:0">
        <div class="date-day">${d.day}</div><div class="date-month">${d.month}</div><div class="date-year">${d.year}</div>
      </div>
      <div class="concert-info">
        <div class="concert-venue" style="font-size:15px">${esc(concertData.venue||concertData.name||'–')}</div>
        <div class="concert-city">${icon('map-pin')} ${esc(concertData.city||'')}</div>
        ${concertData.venue ? venueMapHtml(concertData.venue, concertData.city) : ''}
        ${concertData.time?`<div class="concert-time">${icon('clock')} ${esc(concertData.time)} Uhr</div>`:''}
        ${concertData.inStock!==undefined?`<div style="margin-top:6px;font-size:12px;color:${concertData.inStock?'var(--tickets-color)':'#f87171'}">${concertData.inStock?icon('check')+' Verfügbar':icon('circle-x')+' Ausverkauft'}</div>`:''}
      </div>
    </div>
    ${concertData.link?`<a href="${esc(concertData.link)}" target="_blank" rel="noopener" class="ticket-link-btn" style="margin-bottom:10px;display:inline-flex">${icon('arrow-up-right')} Auf Eventim ansehen</a>`:''}`;
  openModal('notif-event-modal');
}

/**
 * POST the stashed notification concert as a single-concert tour to the
 * server, close the modal and reload all state.
 */
export async function importNotifEvent() {
  if (!_notifImportData) return;
  const {concertData:c, artistName} = _notifImportData;
  const r = await fetch('/api/events',{method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({event_type:'tour',artist:artistName,tour_name:c.name||artistName,
      support:[],poster:null,comment:'',concerts:[{date:c.date||'',time:c.time||null,end_date:null,
      city:c.city||'',venue:c.venue||c.name||'',price:null,ticket_link:c.link||null,tags:[],support_present:[]}]})});
  if (!r.ok){alert('Fehler beim Speichern.');return;}
  closeModal('notif-event-modal');
  await fetchAll();
}

/**
 * Install the 30-minute interval that polls followed artists' Eventim
 * concerts for new events. Idempotent: a no-op if already running.
 */
export function startFavPolling() {
  if (_pollInterval) return;
  _pollInterval = setInterval(checkFavArtistEvents, 30*60*1000);
}

/**
 * For each followed artist with an Eventim name, fetch upcoming concerts
 * and push a notification for every productId not seen in the previous
 * pass. Also refreshes any open fav card's cached concerts. Errors per
 * artist are swallowed so one failure doesn't abort the rest.
 */
export async function checkFavArtistEvents() {
  const followed = state.artists.filter(a=>a.followed&&a.id&&(a.eventim_name||a.name));
  for (const a of followed) {
    const searchName = a.eventim_name||a.name;
    try {
      const r = await fetch(`/api/eventim/artist-events?name=${encodeURIComponent(searchName)}`);
      const data = await r.json();
      if (data.error||!data.concerts) continue;
      const seen = _lastEventimCheck[a.id]||new Set();
      const newC = data.concerts.filter(c=>c.productId&&!seen.has(c.productId));
      if (newC.length && seen.size>0) {
        newC.forEach(c=>{
          state.notifications.push({id:`${a.id}-${c.productId}-${Date.now()}`,artistName:a.name,
            concertName:c.name||'',date:c.date,city:c.city,venue:c.venue,link:c.link,read:false,concertData:c});
        });
        saveNotifications(); updateNotifBadge();
        if (state.favCardState[a.id]) {state.favCardState[a.id].concerts=data.concerts;state.favCardState[a.id].loadedAt=Date.now();}
      }
      _lastEventimCheck[a.id] = new Set(data.concerts.map(c=>c.productId).filter(Boolean));
    } catch(e){}
  }
}

setTimeout(()=>{checkFavArtistEvents();startFavPolling();}, 5000);
updateNotifBadge();
